SELECT 'preferences_table' AS check_name, CASE WHEN to_regclass('public.hq_review_sms_preferences') IS NOT NULL THEN 'READY' ELSE 'MISSING' END AS status
UNION ALL SELECT 'rls',CASE WHEN (SELECT relrowsecurity FROM pg_class WHERE oid='public.hq_review_sms_preferences'::regclass) THEN 'READY' ELSE 'MISSING' END
UNION ALL SELECT 'client_access',CASE WHEN NOT has_table_privilege('anon','public.hq_review_sms_preferences','SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('authenticated','public.hq_review_sms_preferences','SELECT,INSERT,UPDATE,DELETE') AND NOT has_function_privilege('anon','public.get_hq_review_sms_preference_v94(text,bigint)','EXECUTE') AND NOT has_function_privilege('authenticated','public.get_hq_review_sms_preference_v94(text,bigint)','EXECUTE') AND NOT has_function_privilege('anon','public.set_hq_review_sms_preference_v94(text,bigint,boolean)','EXECUTE') AND NOT has_function_privilege('authenticated','public.set_hq_review_sms_preference_v94(text,bigint,boolean)','EXECUTE') THEN 'READY' ELSE 'MISMATCH' END
UNION ALL SELECT 'service_access',CASE WHEN has_function_privilege('service_role','public.get_hq_review_sms_preference_v94(text,bigint)','EXECUTE') AND has_function_privilege('service_role','public.set_hq_review_sms_preference_v94(text,bigint,boolean)','EXECUTE') THEN 'READY' ELSE 'MISSING' END
UNION ALL SELECT 'default_off',CASE WHEN (SELECT column_default FROM information_schema.columns WHERE table_schema='public' AND table_name='hq_review_sms_preferences' AND column_name='enabled')='false' THEN 'READY' ELSE 'MISMATCH' END;
